'<br>',
'  apex_json.open_object;<br>',
'<br>',
'  apex_json.open_object(p_name => "models");<br>',
'<br>',
'  apex_json.open_array(p_name => "data");<br>',
'<br>',
'  apex_json.open_object;<br>',
'<br>',
'  <b>for</b> i in 1..200 <b>loop</b><br>',
'    apex_json.write("id", i);<br>',
'    apex_json.write("name", "Jack Daniel");<br>',
'    apex_json.write("role", "Therapist");<br>',
'  <b>end loop</b>;<br>',
'<br>',
'  apex_json.close_object;<br>',
'<br>',
'  apex_json.open_array;<br>',
'<br>',
'  apex_json.close_object;<br>',
'<br>',
'  apex_json.close_object;<br>',
'<b>end</b>;<br>'))
);
